// =====================================================
// LED FUNCTIONS
// =====================================================

void showSolid() {

  if (!ledsOn) {
    strip.clear();
    strip.show();
    return;
  }

  for (int i = 0; i < LED_COUNT; i++) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );

  }

  strip.show();

}


void setSolid(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentEffect = SOLID;

  currentR = r;
  currentG = g;
  currentB = b;

  ledsOn = true;

  showSolid();

}


// =====================================================
// EFFECT ENGINE
// =====================================================

void updateEffects() {

  if (!ledsOn) return;


  // ---------------------------------------------------
  // RAINBOW
  // ---------------------------------------------------

  if (currentEffect == RAINBOW) {

    if (
      millis() - lastEffectUpdate >= 25
    ) {

      lastEffectUpdate = millis();

      for (int i = 0; i < LED_COUNT; i++) {

        int hue =
          effectStep +
          (i * 65536L / LED_COUNT);

        strip.setPixelColor(
          i,
          strip.gamma32(
            strip.ColorHSV(hue)
          )
        );

      }

      strip.show();

      effectStep += 500;

      if (effectStep >= 65536) {
        effectStep = 0;
      }

    }

  }


  // ---------------------------------------------------
  // PURPLE / WHITE CHASE
  // ---------------------------------------------------

  else if (
    currentEffect ==
    PURPLE_WHITE_CHASE
  ) {

    if (
      millis() - lastEffectUpdate >= 100
    ) {

      lastEffectUpdate = millis();

      for (int i = 0; i < LED_COUNT; i++) {

        if (
          ((i + effectStep) % 6) < 3
        ) {

          // PURPLE
          strip.setPixelColor(
            i,
            strip.Color(
              128,
              0,
              255
            )
          );

        }

        else {

          // WHITE
          strip.setPixelColor(
            i,
            strip.Color(
              255,
              255,
              255
            )
          );

        }

      }

      strip.show();

      effectStep++;

      if (effectStep >= 6) {
        effectStep = 0;
      }

    }

  }

}


